@@ -0,0 +1,8 @@
+import { resolve, sep } from "node:path";
+import { readFile } from "node:fs/promises";
+export async function serveStatic(root: string, requestPath: string) {
+  const base = resolve(root);
+  const file = resolve(base, "." + decodeURIComponent(requestPath));
+  if (file !== base && !file.startsWith(base + sep)) throw new Error("Path outside root");
+  return readFile(file);
+}
